import unittest
from candidate import string_sequence

class TestStringSequence(unittest.TestCase):
    def test_string_sequence_normal_case_expected_behavior(self):
        self.assertEqual(string_sequence(5), '0 1 2 3 4 5')

    def test_string_sequence_boundary_zero(self):
        self.assertEqual(string_sequence(0), '0')

    def test_string_sequence_boundary_one(self):
        self.assertEqual(string_sequence(1), '0 1')

    def test_string_sequence_empty_input_negative_n(self):
        self.assertEqual(string_sequence(-1), '')

    def test_string_sequence_none_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            string_sequence(None)

    def test_string_sequence_string_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            string_sequence('5')

    def test_string_sequence_float_input_raises_typeerror(self):
        with self.assertRaises(TypeError):
            string_sequence(5.5)

if __name__ == '__main__':
    unittest.main()
